function t1211_init(recId){var rec=document.getElementById('rec'+recId);if(!rec)return;t1211_handleCodeBlocks(rec)}
function t1211_handleCodeBlocks(rec){var codeBlocks=rec.querySelectorAll('.t-redactor__highlightcode code');if(!codeBlocks.length)return;t_onFuncLoad('t_loadJsFile',function(){t_loadJsFile('https://static.tildacdn.com/js/highlight.min.js',t1211_addHighlightCodeBlocks.bind(this,codeBlocks))});t_onFuncLoad('t_loadCSSFile',function(){t_loadCSSFile('https://static.tildacdn.com/css/highlight.min.css');t_loadCSSFile('https://fonts.googleapis.com/css2?family=Source+Code+Pro:wght@400;700&display=swap',t1211_addFontFamily.bind(this,codeBlocks))})}
function t1211_addHighlightCodeBlocks(codeBlocks){t_onFuncLoad('hljs',function(){if(!window.hljs.highlightBlock)return;for(var i=0;i<codeBlocks.length;i++){window.hljs.highlightBlock(codeBlocks[i])}})}
function t1211_addFontFamily(codeBlocks){for(var i=0;i<codeBlocks.length;i++){codeBlocks[i].style.fontFamily='"Source Code Pro", monospace'}}